// This file is generated by AI.

// 模板的校验与路径解析 (引用式存储, 不复制文件)。

import { fs } from './fs';
import type { Settings, TemplateEntry } from './settings';
import { bindingKey, type ProjectBinding } from './bindings';

export interface TemplateValidation {
  valid: boolean;
  name: string;
  error?: string;
}

interface TemplateManifest {
  name?: string;
  'webgal-version'?: string;
  webgalVersion?: string;
}

function baseName(path: string): string {
  return (
    path
      .replace(/[\\/]+$/, '')
      .split(/[\\/]/)
      .pop() ?? path
  );
}

/** 校验模板目录: 兼容 template.json 清单与结构回退。 */
export async function validateTemplate(path: string): Promise<TemplateValidation> {
  try {
    const stat = await fs.exists(path);
    if (!stat.exists || !stat.isDirectory) {
      return { valid: false, name: baseName(path), error: '目录不存在' };
    }

    const manifestPath = `${path}\\template.json`;
    const manifestExists = (await fs.exists(manifestPath)).exists;
    if (manifestExists) {
      try {
        const manifest = JSON.parse(await fs.readText(manifestPath)) as TemplateManifest;
        if (manifest.name) {
          return { valid: true, name: manifest.name };
        }
      } catch {
        // manifest 解析失败, 回退
      }
    }

    return { valid: true, name: baseName(path) };
  } catch (e) {
    return { valid: false, name: baseName(path), error: String(e) };
  }
}

/** 解析项目使用的模板条目。 */
export function resolveTemplate(
  settings: Settings,
  bindings: Record<string, ProjectBinding>,
  projectPath: string
): TemplateEntry | null {
  const binding = bindings[bindingKey(projectPath)];
  if (binding?.templateId) {
    return settings.templates.find((t) => t.id === binding.templateId) ?? null;
  }
  return null;
}

export function createId(): string {
  return `tpl-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`;
}
